<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import PropertyCard from '../components/PropertyCard.vue'
import AppSheet from '../components/AppSheet.vue'
import { listings, money } from '../data/mock'
import { usePilotStore } from '../stores/pilot'
const store=usePilotStore(),router=useRouter()
type Panel='saved'|'conversations'|'settings'|'viewings'|'identity'|null
const panel=ref<Panel>(null), savedTab=ref('homes'), nicknameDraft=ref(store.nickname)
const saved=computed(()=>listings.filter(h=>store.savedListings.includes(h.id)))
const savedPlans=computed(()=>store.displayPlans.filter(p=>store.savedPlans.includes(p.id)))
const conversationCount=computed(()=>store.messages.filter(m=>m.role === 'user').length)
const panelOpen=computed({get:()=>panel.value !== null,set:(value:boolean)=>{if(!value)panel.value=null}})
const titles={saved:'我的收藏',conversations:'历史对话',settings:'系统设置',viewings:'看房计划',identity:'个人资料'}
const panelTitle=computed(()=>panel.value ? titles[panel.value] : '')
const viewingHomes=computed(()=>store.viewings.map(v=>({...v,home:listings.find(h=>h.id === v.listingId)!})).filter(v=>v.home))
function togglePanel(name:Panel){panel.value=name;if(name === 'identity')nicknameDraft.value=store.nickname}
function saveIdentity(){const name=nicknameDraft.value.trim();if(!name)return;store.nickname=name.slice(0,16);panel.value=null;store.notify('资料已保存')}
function reopen(id:string){store.openConversation(id);panel.value=null;router.push('/chat')}
</script>

<template>
  <AppHeader hide-avatar><button class="icon-button" aria-label="打开系统设置" @click="togglePanel('settings')"><AppIcon name="settings" /></button></AppHeader>
  <main class="page profile-page stack">
    <section class="profile-identity"><div class="profile-avatar"><AppIcon name="user" :size="30" /></div><div><p class="small muted">我的生活档案</p><h1>{{ store.nickname }}</h1><p class="tiny muted row"><AppIcon name="map-pin" :size="13" />上海</p></div><button class="icon-button" aria-label="编辑个人资料" @click="togglePanel('identity')"><AppIcon name="pencil" :size="18" /></button></section>
    <section class="profile-stats"><button @click="togglePanel('saved')"><strong>{{ saved.length }}</strong><span>收藏房源</span></button><RouterLink to="/history"><strong>{{ store.versions.length }}</strong><span>方案版本</span></RouterLink><button @click="togglePanel('viewings')"><strong>{{ store.viewings.length }}</strong><span>看房计划</span></button></section>
    <section class="current-plan"><div class="between"><h2>当前居住方案</h2><span>{{ store.activeVersionId }}</span></div><RouterLink :to="`/plans/${store.activePlanId}`" class="current-plan-link"><img :src="store.activePlan.image" alt="当前方案社区示意" /><span><strong>{{ store.activePlan.name }}</strong><small>{{ money(store.activePlan.rent) }}/月 · 单程 {{ store.activePlan.commute }} 分钟</small></span><AppIcon name="chevron-right" :size="18" /></RouterLink><RouterLink :to="`/lifesim/${store.activePlanId}`" class="current-plan-sim"><AppIcon name="sun" :size="16" /><span>看看住在这里的一天</span><AppIcon name="arrow-right" :size="16" /></RouterLink></section>
    <section class="management-list">
      <button class="management-item" :aria-expanded="panel === 'saved'" aria-haspopup="dialog" @click="togglePanel('saved')"><AppIcon name="heart" :size="21" /><span>收藏房源</span><small>{{ saved.length }} 套</small><AppIcon name="chevron-right" :size="17" /></button>
      <button class="management-item" :aria-expanded="panel === 'conversations'" aria-haspopup="dialog" @click="togglePanel('conversations')"><AppIcon name="message" :size="21" /><span>历史对话</span><small>{{ store.conversations.length+(store.messages.length ? 1 : 0) }} 个</small><AppIcon name="chevron-right" :size="17" /></button>
      <RouterLink to="/preferences" class="management-item"><AppIcon name="sliders" :size="21" /><span>我的居住偏好</span><AppIcon name="chevron-right" :size="17" /></RouterLink>
      <RouterLink to="/history" class="management-item"><AppIcon name="history" :size="21" /><span>方案版本与对比</span><AppIcon name="chevron-right" :size="17" /></RouterLink>
      <button class="management-item" :aria-expanded="panel === 'settings'" aria-haspopup="dialog" @click="togglePanel('settings')"><AppIcon name="settings" :size="21" /><span>系统设置</span><AppIcon name="chevron-right" :size="17" /></button>
    </section>
    <p class="profile-footer">RentPilot · 把选择留给自己</p>
  </main>
  <AppSheet v-model="panelOpen" :title="panelTitle">
    <section v-if="panel === 'saved'" class="saved-panel stack" aria-label="收藏清单"><div class="pill-tabs" role="tablist" aria-label="收藏类型"><button role="tab" :aria-selected="savedTab === 'homes'" @click="savedTab='homes'">房源 {{ saved.length }}</button><button role="tab" :aria-selected="savedTab === 'plans'" @click="savedTab='plans'">方案 {{ savedPlans.length }}</button></div><template v-if="savedTab === 'homes'"><PropertyCard v-for="home in saved" :key="home.id" :home="home" compact /><div v-if="!saved.length" class="panel-empty"><AppIcon name="heart" :size="30" /><h3>还没有收藏的房源</h3><p>遇到心动的房子，点一下爱心。</p><RouterLink to="/map" class="secondary" @click="panel=null">去发现房源<AppIcon name="arrow-right" :size="16" /></RouterLink></div></template><template v-else><RouterLink v-for="plan in savedPlans" :key="plan.id" :to="`/plans/${plan.id}`" class="saved-plan" @click="panel=null"><img :src="plan.image" alt="社区示意" /><span><strong>{{ plan.name }}</strong><small>{{ money(plan.rent) }}/月 · {{ plan.commute }} 分钟</small></span><AppIcon name="chevron-right" :size="17" /></RouterLink><div v-if="!savedPlans.length" class="panel-empty"><AppIcon name="bookmark" :size="30" /><h3>还没有保存的方案</h3><p>先看看不同生活方式的取舍。</p><RouterLink to="/plans" class="secondary" @click="panel=null">探索居住方案<AppIcon name="arrow-right" /></RouterLink></div></template></section>
    <section v-if="panel === 'conversations'" class="stack"><RouterLink v-if="store.messages.length" to="/chat" class="conversation-link" @click="panel=null"><AppIcon name="message" /><span><strong>继续当前对话</strong><small>{{ conversationCount }} 轮需求沟通</small></span><AppIcon name="arrow-right" :size="17" /></RouterLink><button v-for="conversation in store.conversations" :key="conversation.id" class="conversation-link" @click="reopen(conversation.id)"><AppIcon name="history" /><span><strong>{{ conversation.title }}</strong><small>{{ new Date(conversation.updatedAt).toLocaleDateString('zh-CN') }}</small></span><AppIcon name="chevron-right" :size="17" /></button><div v-if="!store.messages.length && !store.conversations.length" class="panel-empty"><AppIcon name="message" :size="30" /><h3>从一次对话开始</h3><p>预算、工作地，或想要的生活。</p><RouterLink to="/chat" class="primary" @click="panel=null">开始找房<AppIcon name="arrow-right" /></RouterLink></div></section>
    <section v-if="panel === 'viewings'" class="stack"><p v-if="viewingHomes.length" class="tiny muted">本地看房安排，尚未向任何经纪人提交预约。</p><article v-for="viewing in viewingHomes" :key="viewing.id" class="viewing-card"><RouterLink :to="`/listing/${viewing.listingId}`" class="saved-plan" @click="panel=null"><img :src="viewing.home.image" alt="房源示意" /><span><strong>{{ viewing.home.name }}</strong><small>{{ viewing.date }} · {{ viewing.slot }}</small></span><AppIcon name="chevron-right" :size="16" /></RouterLink><button class="text-action muted" aria-label="取消这条看房计划" @click="store.cancelViewing(viewing.id)">取消计划</button></article><div v-if="!viewingHomes.length" class="panel-empty"><AppIcon name="calendar" :size="30" /><h3>还没有看房计划</h3><p>挑一套喜欢的房子，安排一次实地了解。</p><RouterLink to="/map" class="secondary" @click="panel=null">去看看房源<AppIcon name="arrow-right" /></RouterLink></div></section>
    <section v-if="panel === 'settings'" class="stack"><div class="between"><div><h3>房源变动提醒</h3><p class="small muted">仅保存本地偏好，不发送推送</p></div><button class="toggle" :class="{enabled:store.notifications}" role="switch" :aria-checked="store.notifications" aria-label="本地 Mock 房源通知偏好" @click="store.notifications=!store.notifications"><span></span></button></div><div class="settings-about"><h3>关于 RentPilot</h3><p class="small muted">MVP · Vue 3 + Capacitor<br />房源、AI、地图及生活模拟使用示例数据。收藏与对话保存在本机，卸载或清除应用数据后会丢失。</p></div></section>
    <section v-if="panel === 'identity'" class="stack"><label class="form-field">怎么称呼你<input v-model="nicknameDraft" aria-label="昵称" maxlength="16" /></label><div class="form-field"><span>居住城市</span><p class="muted">上海</p></div></section>
    <template v-if="panel === 'identity'" #footer><button class="primary" :disabled="!nicknameDraft.trim()" @click="saveIdentity">保存资料<AppIcon name="check" /></button></template>
  </AppSheet>
</template>

<style scoped>
.profile-page{padding-top:16px;gap:28px}.profile-identity{display:flex;gap:16px;align-items:center}.profile-avatar{width:64px;height:64px;border-radius:50%;background:var(--surface);display:grid;place-items:center;flex-shrink:0}.profile-identity>div:nth-child(2){flex:1;min-width:0}.profile-identity h1{font-size:23px;letter-spacing:-.025em;overflow-wrap:anywhere;margin:4px 0}.profile-identity .tiny{gap:4px;margin-top:6px}.profile-identity>.icon-button{margin-right:-10px}.profile-identity .small{font-size:12px}.profile-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:16px 0;border-bottom:1px solid var(--line)}.profile-stats>*{display:flex;flex-direction:column;align-items:center;gap:10px;min-height:70px}.profile-stats>*+*{border-left:1px solid var(--line)}.profile-stats strong{font-size:30px;font-weight:500;line-height:1.3}.profile-stats span{font-size:12px;color:var(--muted)}.current-plan{padding:20px;background:var(--surface);border-radius:20px}.current-plan>.between h2{font-size:14px;font-weight:500}.current-plan>.between>span{font-size:12px;color:var(--muted)}.current-plan-link{display:flex;align-items:center;gap:14px;padding:20px 0}.current-plan-link img{width:64px;height:70px;border-radius:12px;flex-shrink:0}.current-plan-link>span{flex:1;min-width:0}.current-plan-link strong{font-size:15px;font-weight:600;display:block}.current-plan-link small{display:block;font-size:12px;color:var(--muted);margin-top:10px}.current-plan-sim{border-top:1px solid #dedede;padding-top:16px;display:flex;align-items:center;gap:9px;font-size:12px}.current-plan-sim>span{flex:1}.management-list{display:flex;flex-direction:column}.management-item{display:flex;align-items:center;gap:16px;text-align:left;min-height:64px;padding:10px 0;width:100%;font-size:14px;border-bottom:1px solid var(--line)}.management-item>span{flex:1}.management-item>small{font-size:12px;color:var(--muted)}.management-item>svg:last-child{color:var(--muted)}.profile-footer{text-align:center;font-size:12px;color:var(--muted);padding-top:2px}.panel-empty{text-align:center;padding:24px 8px}.panel-empty>svg{margin:0 auto 16px}.panel-empty p{font-size:13px;color:var(--muted);margin-top:10px}.panel-empty .secondary,.panel-empty .primary{margin-top:24px}.saved-panel{gap:12px}.saved-panel>.pill-tabs{margin-bottom:8px}.saved-plan,.conversation-link{display:flex;align-items:center;gap:14px;text-align:left;width:100%;min-height:68px;padding:12px 0}.saved-plan>img{width:70px;height:76px;border-radius:12px;flex-shrink:0}.saved-plan>span,.conversation-link>span{flex:1;min-width:0}.saved-plan strong,.conversation-link strong{font-size:14px;font-weight:500;line-height:1.7;display:block;overflow-wrap:anywhere}.saved-plan small,.conversation-link small{font-size:12px;color:var(--muted);display:block;margin-top:8px}.viewing-card{border-bottom:1px solid var(--line)}.viewing-card>.text-action{display:flex;margin-left:auto;font-size:12px}.settings-about{border-top:1px solid var(--line);padding-top:22px}.settings-about p{margin-top:12px}
@media(max-width:359px){.profile-avatar{width:54px;height:54px}.profile-identity{gap:12px}.profile-identity h1{font-size:21px}.current-plan{padding:16px}.current-plan-link{gap:10px}.current-plan-link strong{font-size:14px}.current-plan-link small{font-size:12px}}
</style>